<?php $rows=db()->query('SELECT * FROM commitments ORDER BY id DESC')->fetchAll(); ?>
<div class="card p-3"><h5>Commitments / Spend Summary</h5><table class="table table-sm"><tr><th>PR Ref</th><th>PO Ref</th><th>Estimated</th><th>Committed</th><th>Released</th><th>Exposure</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['pr_reference'])?></td><td><?=e($r['po_reference'])?></td><td><?=number_format((float)$r['pr_estimated_amount'],2)?></td><td><?=number_format((float)$r['po_committed_amount'],2)?></td><td><?=number_format((float)$r['released_amount'],2)?></td><td><?=number_format((float)$r['pending_exposure'],2)?></td></tr><?php endforeach;?></table></div>
